llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Esaxerenone, a close analogue sharing the methylsulfonyl-phenyl and heteroaromatic core, had absolute oral bioavailability of 89.0% in healthy Japanese subjects under fasting conditions, directly supporting high F for the query in the fasted state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Iclepertin (BI 425809), which also contains a methylsulfonyl-phenyl group, showed absolute bioavailability of 71.64% (90% CI 64.3-79.9) for a fasted 25 mg tablet in healthy participants, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Odanacatib, a methylsulfonyl-phenyl biaryl analogue, had absolute bioavailability of 30% for a 50 mg fasted dose; although lower than other analogues, this remains above the 20% threshold and supports the high classification while flagging possible solubility-limited absorption at high doses.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Basmisanil, a heteroaromatic sulfonyl-containing drug, had absolute bioavailability of approximately 75% in humans after oral tablet administration, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Imatinib, despite a different core, demonstrates near-complete oral absorption with absolute bioavailability of 97.2% versus IV, supporting that neutral, moderately polar, low-HBD molecules can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Pradigastat had moderate absolute bioavailability of approximately 40% in humans, still above the 20% threshold, supporting high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Bitopertin, containing a methylsulfonyl-phenyl and amide motif, had high absolute bioavailability based on the minor effect of CYP3A4 inhibition on exposure, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues, including several with direct fasting-state absolute bioavailability measurements, show F values well above 20% (30-98%). The query shares key structural features with these compounds, especially the methylsulfonyl-phenyl and heteroaromatic biaryl system, and no affirmative evidence supports F < 20%. Therefore the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule.",
    "The oral dose is unspecified; solubility-limited absorption at high doses, as seen with odanacatib, could lower F but is unlikely to drop below 20% based on the analogue range.",
    "Metabolic stability and first-pass extraction for the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

